css:
.article-preview { color: var(--color-article-ink); }
.article-preview .article-body { max-width: 40rem; margin: 0 auto; padding: 24px 20px 40px; }
.article-preview .article-body > :first-child { margin-top: 0; }
.article-preview .article-body h1,
.article-preview .article-body h2,
.article-preview .article-body h3,
.article-preview .article-body h4,
.article-preview .article-body h5,
.article-preview .article-body h6 { color: var(--color-article-heading); font-weight: 700; }
.article-preview .article-body h1 { font-size: 28px; line-height: 1.45; letter-spacing: 0.01em; margin: 0 0 24px; padding-bottom: 18px; border-bottom: 1px solid var(--color-article-line); }
.article-preview .article-body h2 { font-size: 23px; line-height: 1.5; margin: 36px 0 20px; padding-bottom: 16px; border-bottom: 1px solid var(--color-article-line); }
.article-preview .article-body h3 { font-size: 18px; line-height: 1.6; margin: 28px 0 16px; padding-left: 12px; border-left: 3px solid var(--color-article-accent); }
.article-preview .article-body h4 { color: var(--color-article-heading); font-size: 12px; line-height: 1.7; letter-spacing: 0.12em; margin: 24px 0 12px; }
.article-preview .article-body h5,
.article-preview .article-body h6 { font-size: 14px; line-height: 1.7; margin: 22px 0 10px; }
.article-preview .article-body p { font-size: 16px; line-height: 1.9; margin: 0 0 18px; }
.article-preview .article-body strong { color: var(--color-article-heading); font-weight: 700; }
.article-preview .article-body em { font-style: italic; }
.article-preview .article-body a { color: var(--color-article-heading); text-decoration: underline; text-underline-offset: 0.2em; }
.article-preview .article-body del { color: var(--color-article-muted); }
.article-preview .article-body blockquote { margin: 24px 0; padding: 0 0 0 16px; border-left: 3px solid var(--color-article-accent); color: var(--color-article-heading); font-size: 18px; line-height: 1.8; font-weight: 600; }
.article-preview .article-body blockquote p { color: inherit; font-size: inherit; line-height: inherit; margin: 0 0 10px; }
.article-preview .article-body blockquote p:last-child { margin-bottom: 0; }
.article-preview .article-body ul { margin: 18px 0; padding-left: 24px; }
.article-preview .article-body ol { margin: 18px 0; padding-left: 24px; }
.article-preview .article-body li { font-size: 16px; line-height: 1.9; margin-bottom: 8px; }
.article-preview .article-body li p { margin-bottom: 8px; }
.article-preview .article-body li li { margin-bottom: 4px; }
.article-preview .article-body code { color: var(--color-article-heading); background-color: var(--color-article-code-tint); font-size: 13px; line-height: 1.7; padding: 2px 4px; }
.article-preview .article-body pre { color: var(--color-article-code); background-color: var(--color-article-code-surface); font-size: 13px; line-height: 1.8; padding: 16px; border-radius: 0; overflow-x: auto; }
.article-preview .article-body pre code { color: inherit; background-color: transparent; font-size: inherit; line-height: inherit; padding: 0; white-space: nowrap; }
.article-preview .article-body table { width: 100%; border-collapse: collapse; margin: 24px 0; font-size: 14px; line-height: 1.8; }
.article-preview .article-body th { padding: 10px 12px; color: var(--color-article-heading); background-color: var(--color-article-tint); border-bottom: 1px solid var(--color-article-line); text-align: left; font-weight: 700; }
.article-preview .article-body td { padding: 10px 12px; border-bottom: 1px solid var(--color-article-line); vertical-align: top; }
.article-preview .article-body hr { border: 0; border-bottom: 1px solid var(--color-article-line); margin: 28px 0; }
.article-preview .article-body figure { margin: 24px 0; }
.article-preview .article-body img { max-width: 100%; height: auto; display: block; }
.article-preview .article-body figcaption { color: var(--color-article-muted); font-size: 12px; line-height: 1.8; margin-top: 10px; text-align: center; }
.article-preview .article-body small,
.article-preview .article-body sup { color: var(--color-article-muted); font-size: 12px; line-height: 1.8; }
.article-preview .article-body .theme-sample-image { padding: 36px 16px; border: 1px solid var(--color-article-line); background-color: var(--color-article-tint); color: var(--color-article-muted); text-align: center; font-size: 13px; line-height: 1.8; }
.article-preview .article-body blockquote p + p { color: var(--color-article-muted); font-size: 13px; line-height: 1.8; font-weight: 400; }
